CREATE TABLE IF NOT EXISTS tl_control (id INT PRIMARY KEY, value_int INT NOT NULL);
INSERT IGNORE INTO tl_control VALUES (1,0);
CREATE TABLE IF NOT EXISTS tl_users (id CHAR(36) PRIMARY KEY,email VARCHAR(254) NOT NULL UNIQUE,password_hash VARCHAR(256) NOT NULL,created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS tl_sessions (token_hash CHAR(64) PRIMARY KEY,user_id CHAR(36) NOT NULL,expires_at BIGINT NOT NULL,INDEX(user_id),INDEX(expires_at),FOREIGN KEY(user_id) REFERENCES tl_users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS tl_limits (limit_key CHAR(64) PRIMARY KEY,window_start BIGINT NOT NULL,hits INT NOT NULL);
CREATE TABLE IF NOT EXISTS tl_devices (id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,label VARCHAR(80) NOT NULL,account_hash CHAR(64),last_timestamp BIGINT NOT NULL DEFAULT 0,revoked BOOLEAN NOT NULL DEFAULT FALSE,created_at BIGINT NOT NULL,FOREIGN KEY(user_id) REFERENCES tl_users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS tl_trades (user_id CHAR(36) NOT NULL,source VARCHAR(12) NOT NULL,trade_id VARCHAR(120) NOT NULL,payload LONGTEXT NOT NULL,PRIMARY KEY(user_id,source,trade_id),FOREIGN KEY(user_id) REFERENCES tl_users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS tl_notes (user_id CHAR(36) NOT NULL,source VARCHAR(12) NOT NULL,day CHAR(10) NOT NULL,note TEXT NOT NULL,PRIMARY KEY(user_id,source,day),FOREIGN KEY(user_id) REFERENCES tl_users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS tl_settings (user_id CHAR(36) PRIMARY KEY,initial_balance DECIMAL(18,2) NOT NULL DEFAULT 0,FOREIGN KEY(user_id) REFERENCES tl_users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS tl_snapshots (user_id CHAR(36) PRIMARY KEY,device_id CHAR(36) NOT NULL,payload LONGTEXT NOT NULL,FOREIGN KEY(user_id) REFERENCES tl_users(id) ON DELETE CASCADE);
